class Solution {
    public int rearrangeCharacters(String s,String target){
        int[] source=new int[26],need=new int[26];
        for(char ch:s.toCharArray())source[ch-'a']++;
        for(char ch:target.toCharArray())need[ch-'a']++;
        int answer=Integer.MAX_VALUE;
        for(int i=0;i<26;i++)if(need[i]>0)answer=Math.min(answer,source[i]/need[i]);
        return answer;
    }
}

code.kotlin:
class Solution {
    fun rearrangeCharacters(s:String,target:String):Int{
        val source=IntArray(26);
        val need=IntArray(26);
        for(ch in s)source[ch-'a']++;
        for(ch in target)need[ch-'a']++;
        var answer=Int.MAX_VALUE;
        for(i in 0 until 26)if(need[i]>0)answer=minOf(answer,source[i]/need[i]);
        return answer
    }
}

